mapper.update:
update user_book_list
set list_name = #{listName},
    description = #{description},
    update_time = #{updateTime}
where id = #{id}

update user_book_list
set status = 0, update_time = now()
where id = #{id}

mapper.select:
select count(1)
from user_book_list
where user_id = #{userId}
  and list_name = #{listName}
  and status = 1

    and id != #{excludeId}

select count(1)
from user_book_list_item
where list_id = #{listId} and book_id = #{bookId}
